interface.signature:
interface FileSystemDirectoryHandle {
  getFileHandle(name: string, options?: { create?: boolean }): Promise<FileSystemFileHandle>;
}

interface FileSystemFileHandle {
  createWritable(): Promise<FileSystemWritableFileStream>;
}

interface FileSystemWritableFileStream {
  write(data: BufferSource | Blob | string): Promise<void>;
  close(): Promise<void>;
}

function showDirectoryPicker(options?: { mode?: 'read' | 'readwrite', startIn?: string }): Promise<FileSystemDirectoryHandle>;

interface PartitionStore {
  partitions: PartitionInfo[];
  selectedPartitions: Set<string>;
  // ... other state and actions
}

interface FlashStore {
  // Existing flash state...

  // NEW: Backup state
  backupStatus: 'idle' | 'preparing' | 'backing-up' | 'success' | 'error' | 'cancelled';
  currentBackupPartition: string | null;
  backupProgress: number;
  backupBytesWritten: number;
  backupTotalBytes: number;
  backupPartitionStatuses: Map<string, 'pending' | 'in-progress' | 'done' | 'error'>;
  backupError: AppError | null;
  backupSavePath: string | null;

  // NEW: Backup actions
  startBackup: (partitions: string[], savePath: string) => void;
  updateBackupProgress: (partition: string, bytesWritten: number, totalBytes: number) => void;
  setBackupPartitionStatus: (partition: string, status: PartitionStatus) => void;
  completeBackup: () => void;
  cancelBackup: () => void;
  resetBackup: () => void;
}

interface TerminalStore {
  log: (level: 'info' | 'success' | 'warning' | 'error', message: string) => void;
  // ... other state and actions
}

interface UseBackupReturn {
  startBackup: (partitions: PartitionInfo[], directoryHandle: FileSystemDirectoryHandle) => Promise<void>;
  cancelBackup: () => void;
}

function useBackup(): UseBackupReturn;

interface BackupConfirmDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  partitions: PartitionInfo[];
  onConfirm: (directoryHandle: FileSystemDirectoryHandle) => void;
}

function BackupConfirmDialog(props: BackupConfirmDialogProps): JSX.Element;

interface BackupProgressProps {
  className?: string;
}

function BackupProgress(props: BackupProgressProps): JSX.Element;
